 1→import { createContext, useContext } from 'react';
 2→
 3→type Theme = 'light' | 'dark';
 4→
 5→interface ThemeContextValue {
 6→  theme: Theme;
 7→  toggleTheme: () => void;
 8→}
 9→
10→export const ThemeContext = createContext<ThemeContextValue | null>(null);
11→
12→export function useTheme() {
13→  const ctx = useContext(ThemeContext);
14→  if (!ctx) throw new Error('useTheme must be used within ThemeProvider');
15→  return ctx;
16→}
