  background: var(--color-bg-code);
  padding: 8px 12px;
  border-radius: 6px;
  overflow-x: auto;
  font-size: 12px;
}

.message-bubble__segment-content code {
  background: var(--color-bg-code);
  padding: 1px 4px;
  border-radius: 3px;
  font-size: 13px;
}

.message-bubble__segment-content pre code {
  background: none;
  padding: 0;
}

.message-bubble__segment-content table {
  border-collapse: collapse;
  width: 100%;
  margin: 8px 0;
  font-size: 13px;
  overflow-x: auto;
  display: block;
}

.message-bubble__segment-content th,
.message-bubble__segment-content td {
  border: 1px solid var(--color-border-dark);
  padding: 6px 10px;
  text-align: left;
  white-space: nowrap;
}

.message-bubble__segment-content th {
  background: var(--color-bg-code);
  font-weight: 600;
}

.message-bubble__segment-content tr:nth-child(even) {
  background: var(--color-bg-secondary);
}

/* Collapsible thinking segments */
.message-bubble__collapsible {
  cursor: default;
}

.message-bubble__collapsible-summary {
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  list-style: none;
  user-select: none;
}

.message-bubble__collapsible-summary::-webkit-details-marker {
  display: none;
}

.message-bubble__collapsible-summary::before {
  content: '▶';
  font-size: 9px;
  color: var(--color-text-disabled);
  transition: transform 0.15s ease;
  flex-shrink: 0;
}

.message-bubble__collapsible[open] > .message-bubble__collapsible-summary::before {
  transform: rotate(90deg);
}

.message-bubble__collapsible-summary .message-bubble__segment-label {
  margin-bottom: 0;
  flex-shrink: 0;
}

.message-bubble__collapsible-preview {
  font-size: 12px;
  color: var(--color-text-disabled);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}

.message-bubble__collapsible[open] > .message-bubble__collapsible-summary .message-bubble__collapsible-preview {
  display: none;
}

.message-bubble__thinking-body {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 8px;
}

.message-bubble__tool-segment {
  margin: 2px 0;
}

/* Hover actions for user messages */
.message-bubble__actions {
  display: none;
  margin-left: auto;
  gap: 4px;
}

.message-bubble--user:hover .message-bubble__actions {
  display: inline-flex;
}

.message-bubble__action-btn {
  background: none;
  border: none;
  cursor: pointer;
  padding: 2px 4px;
  font-size: 14px;
  color: var(--color-text-disabled);
  border-radius: 4px;
  line-height: 1;
}

.message-bubble__action-btn:hover {
  background: var(--color-border-light);
  color: var(--color-text-tertiary);
}

.message-bubble__action-btn--delete:hover {
  background: var(--color-error-bg-hover);
  color: var(--color-error);
}

/* Edit mode */
.message-bubble__edit-mode {
  margin-top: 4px;
}

.message-bubble__edit-textarea {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--color-accent-primary-border);
  border-radius: 6px;
  font-size: 14px;
  font-family: inherit;
  line-height: 1.5;
  resize: vertical;
  background: var(--color-bg-primary);
  color: var(--color-text-secondary);
  box-sizing: border-box;
}

.message-bubble__edit-textarea:focus {
  outline: none;
  border-color: var(--color-accent-primary-light);
  box-shadow: 0 0 0 2px var(--color-accent-primary-shadow-strong);
}

.message-bubble__edit-actions {
  display: flex;
  gap: 8px;
  margin-top: 6px;
}

.message-bubble__edit-btn {
  padding: 4px 12px;
  border: 1px solid var(--color-border-dark);
  border-radius: 6px;
  font-size: 12px;
  cursor: pointer;
  background: var(--color-bg-primary);
  color: var(--color-text-tertiary);
}

.message-bubble__edit-btn:hover {
  background: var(--color-bg-code);
}

.message-bubble__edit-btn--save {
  background: var(--color-accent-primary-hover);
  color: var(--color-bg-primary);
  border-color: var(--color-accent-primary-hover);
}

.message-bubble__edit-btn--save:hover {
  background: var(--color-accent-primary-active);
}

/* Delete confirmation */
.message-bubble__confirm-delete {
  margin-top: 4px;
  padding: 8px 10px;
  background: var(--color-error-bg);
  border: 1px solid var(--color-error-border-light);
  border-radius: 6px;
  font-size: 13px;
